// solutions/ontological/lib/services/shell/functions.ts
var FISH_FUNCTIONS = `# sdlc shell integration — generated by \`sdlc shell init fish\`.
# Add to ~/.config/fish/config.fish:   sdlc shell init fish | source

function sdlc-cd --description 'cd to the directory an sdlc op resolves (via --print-path)'
    set -l out (sdlc $argv --print-path)
    or return
    if test (count $out) -ne 1
        echo "sdlc-cd: expected one path, got "(count $out)" lines" >&2
        return 1
    end
    if not string match -q '/*' -- $out[1]
        echo "sdlc-cd: not an absolute path: $out[1]" >&2
        return 1
    end
    if not test -d $out[1]
        echo "sdlc-cd: not a directory: $out[1]" >&2
        return 1
    end
    cd $out[1]
end

function sdlc-at --description 'cd to what an sdlc op resolves, then run the op there'
    sdlc-cd $argv
    and sdlc $argv
end

function sdlc-pr-review --description 'Open a PR in its worktree, cd there, start the review session'
    sdlc-at pr review $argv
end

function sdlc-repo-checkout --description 'Clone a repository (or find its checkout) and cd there'
    sdlc-cd repo checkout $argv
end
`;
var BASH_FUNCTIONS = `# sdlc shell integration — generated by \`sdlc shell init bash\` (zsh reads this too).
# Add to ~/.bashrc or ~/.zshrc:   eval "$(sdlc shell init bash)"

sdlc-cd() {
  local out
  out="$(sdlc "$@" --print-path)" || return
  case "$out" in
    *$'\\n'*) echo "sdlc-cd: expected one path, got several lines" >&2; return 1 ;;
    /*) ;;
    *) echo "sdlc-cd: not an absolute path: $out" >&2; return 1 ;;
  esac
  if [ ! -d "$out" ]; then
    echo "sdlc-cd: not a directory: $out" >&2
    return 1
  fi
  cd -- "$out"
}

sdlc-at() {
  sdlc-cd "$@" && sdlc "$@"
}

sdlc-pr-review() {
  sdlc-at pr review "$@"
}

sdlc-repo-checkout() {
  sdlc-cd repo checkout "$@"
}
`;
function functionsFor(shell) {
  return shell === "fish" ? FISH_FUNCTIONS : BASH_FUNCTIONS;
}

